// src/lifetime.ts
function createLifetime() {
  const removers = [];
  let disposed = false;
  return {
    listen(target, type, handler) {
      if (disposed) return;
      target.addEventListener(type, handler);
      removers.push(() => target.removeEventListener(type, handler));
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      for (const remove of removers.splice(0).reverse()) remove();
    }
  };
}

