// src/demo.ts
function createDemo() {
  let sequence = 3;
  const messages = [
    { id: "demo-1", sender: "friend", text: "路口的小花店开门啦。\n橱窗里有一小束粉色雏菊。", sample: true },
    { id: "demo-2", sender: "self", text: "那就在那里碰面吧 ♡", sample: true },
    { id: "demo-3", sender: "friend", text: "好呀，给你留一朵。", sample: true }
  ];
  return {
    list: () => messages,
    send(text) {
      const value = text.trim();
      if (!value || value.length > 2e3) return null;
      const message = { id: `demo-${++sequence}`, sender: "self", text: value, sample: false };
      messages.push(message);
      return message;
    },
    clear() {
      messages.length = 0;
    }
  };
}

